# 컴포넌트 저장소: 컴포넌트 종류별 entity_id -> 데이터
position = {}
velocity = {}
next_id = 0

def create_entity(**components):
    global next_id
    eid = next_id  # 엔티티는 단순 식별자
    next_id += 1
    if 'pos' in components:
        position[eid] = components['pos']
    if 'vel' in components:
        velocity[eid] = components['vel']
    return eid

def movement_system(dt):
    # 두 컴포넌트를 모두 가진 엔티티만 일괄 처리
    for eid in position.keys() & velocity.keys():
        x, y = position[eid]
        vx, vy = velocity[eid]
        position[eid] = (x + vx * dt, y + vy * dt)

def game_loop(dt):
    movement_system(dt)  # 시스템을 순서대로 실행
